def maxCoins(coins, amount):
    rest = amount - sum(coins)
    if rest < 0:
        return -1
    best = [-1] * (rest + 1)
    best[0] = 0
    for s in range(1, rest + 1):
        top = -1
        for c in coins:
            if c <= s and best[s - c] >= 0 and best[s - c] + 1 > top:
                top = best[s - c] + 1
        best[s] = top
    if best[rest] < 0:
        return -1
    return len(coins) + best[rest]
